CREATE TABLE IF NOT EXISTS "cliente" (
	"rut" INTEGER NOT NULL UNIQUE,
	"nombre" VARCHAR(255) NOT NULL,
	"fono" INTEGER NOT NULL,
	PRIMARY KEY("rut")
);

CREATE TABLE IF NOT EXISTS "vehiculo_cliente" (
	"patente" VARCHAR(255) NOT NULL,
	"kilometraje" NUMERIC NOT NULL,
	"id_modelo" INTEGER NOT NULL,
	"rut_cliente" INTEGER NOT NULL,
	PRIMARY KEY("patente")
);

CREATE TABLE IF NOT EXISTS "venta" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"iva" INTEGER NOT NULL,
	"rut_cliente" INTEGER NOT NULL,
	"patente_vehiculo" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "marca_vehiculo" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"marca" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "modelo_vehiculo" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"modelo" VARCHAR(255) NOT NULL,
	"id_marca" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "producto" (
	"codigo_producto" INTEGER NOT NULL,
	"cod_barra" VARCHAR(255),
	"stock" INTEGER NOT NULL,
	"medida" VARCHAR(255),
	"calidad" INTEGER,
	"tipo" INTEGER,
	"precio" INTEGER NOT NULL,
	PRIMARY KEY("codigo_producto")
);

CREATE TABLE IF NOT EXISTS "tipo_producto" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nombre_tipo" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "calidad_producto" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nombre_calidad" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "servicio" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"descripcion" VARCHAR(255) NOT NULL,
	"costo" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "detalle_venta_producto" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_venta" INTEGER NOT NULL,
	"codigo_producto" INTEGER NOT NULL,
	"total" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "detalle_venta_servicio" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_venta" INTEGER NOT NULL,
	"id_servicio" INTEGER NOT NULL,
	"total" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

ALTER TABLE "producto"
ADD FOREIGN KEY("calidad") REFERENCES "calidad_producto"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "producto"
ADD FOREIGN KEY("tipo") REFERENCES "tipo_producto"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "vehiculo_cliente"
ADD FOREIGN KEY("rut_cliente") REFERENCES "cliente"("rut")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "vehiculo_cliente"
ADD FOREIGN KEY("id_modelo") REFERENCES "modelo_vehiculo"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "detalle_venta_producto"
ADD FOREIGN KEY("codigo_producto") REFERENCES "producto"("codigo_producto")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "detalle_venta_servicio"
ADD FOREIGN KEY("id_servicio") REFERENCES "servicio"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "detalle_venta_servicio"
ADD FOREIGN KEY("id_venta") REFERENCES "venta"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "detalle_venta_producto"
ADD FOREIGN KEY("id_venta") REFERENCES "venta"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venta"
ADD FOREIGN KEY("rut_cliente") REFERENCES "cliente"("rut")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "modelo_vehiculo"
ADD FOREIGN KEY("id_marca") REFERENCES "marca_vehiculo"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "venta"
ADD FOREIGN KEY("patente_vehiculo") REFERENCES "vehiculo_cliente"("patente")
ON UPDATE NO ACTION ON DELETE NO ACTION;